MARK = '@ ---- Johto route trainers (johto_route_trainers.py) ----'
trainers = []
for f in FINAL:
    if f['first']: trainers.append(f['trainer'])
def sym(c): return 'sParty_' + ''.join(w.capitalize() for w in c[len('TRAINER_'):].split('_'))

# ---------------------------------------------------------------- constants
p = 'include/constants/opponents.h'; t = rd(p)
if trainers[0]['const'] not in t:
    n = int(re.search(r'#define NUM_TRAINERS\s+(\d+)', t).group(1))
    last = re.search(r'#define TRAINER_COOL_COUPLE_KUMQUAT_LEX_NYA\s+\d+\n', t).group(0)
    t = t.replace(last, last + '\n// Johto route trainers\n' + ''.join('#define %-40s %d\n' % (tr['const'], n + i) for i, tr in enumerate(trainers)), 1)
    t = re.sub(r'#define NUM_TRAINERS\s+\d+', '#define NUM_TRAINERS                             %d' % (n + len(trainers)), t)
    wr(p, t)

# ---------------------------------------------------------------- parties
p = 'src/data/trainer_parties.h'; t = rd(p)
if sym(trainers[0]['const']) not in t:
    t = t.rstrip('\n') + '\n\n// Johto route trainers (Crystal parties, evolved and scaled)\n'
    for i, tr in enumerate(trainers):
        t += 'static const struct TrainerMonNoItemDefaultMoves %s[] = {\n' % sym(tr['const'])
        for m in tr['mons']:
            t += '    {\n        .iv = %d,\n        .lvl = %d,\n        .species = %s,\n    },\n' % (
                150 if tr['ai'] == 'AI_LEVEL_NORMAL' else 200, m['lvl'], m['species'])
        t += '};\n\n'
    wr(p, t)

# ---------------------------------------------------------------- trainers
p = 'src/data/trainers.h'; t = rd(p)
if '[%s]' % trainers[0]['const'] not in t:
    ent = ''
    for tr in trainers:
        music = 'TRAINER_ENCOUNTER_MUSIC_' + tr['music'] + (' | F_TRAINER_FEMALE' if tr['female'] else '')
        ent += ('    [%s] = {\n        .trainerClass = TRAINER_CLASS_%s,\n        .encounterMusic_gender = %s,\n'
                '        .trainerPic = TRAINER_PIC_%s,\n        .trainerName = _("%s"),\n        .items = {},\n'
                '        .doubleBattle = %s,\n        .aiFlags = %s,\n        .party = NO_ITEM_DEFAULT_MOVES(%s),\n    },\n') % (
                tr['const'], tr['class'], music, tr['pic'], tr['name'], 'TRUE' if tr['double'] else 'FALSE', tr['ai'], sym(tr['const']))
    i = t.index('    [TRAINER_COOL_COUPLE_KUMQUAT_LEX_NYA] = {'); j = t.index('    },\n', i) + len('    },\n')
    t = t[:j] + ent + t[j:]
    wr(p, t)

# ---------------------------------------------------------------- maps
bymap = {}
for f in FINAL: bymap.setdefault(f['map'], []).append(f)
for mp, fs in bymap.items():
    p = 'data/maps/%s/map.json' % mp
    mj = json.loads(rd(p))
    have = {o.get('script') for o in mj.get('object_events', [])}
    for f in fs:
        if f['script'] in have: continue
        mj.setdefault('object_events', []).append({
            'type': 'object', 'graphics_id': f['gfx'], 'x': f['x'], 'y': f['y'], 'elevation': f['elev'],
            'movement_type': f['move'], 'movement_range_x': 1, 'movement_range_y': 1,
            'trainer_type': 'TRAINER_TYPE_NORMAL', 'trainer_sight_or_berry_tree_id': str(f['sight']),
            'script': f['script'], 'flag': '0'})
    wr(p, json.dumps(mj, indent=2, ensure_ascii=False) + '\n')

    p = 'data/maps/%s/scripts.inc' % mp
    t = rd(p)
    if MARK in t: continue
    s = '\n' + MARK + '\n'
    texts = ''
    for f in fs:
        tr = f['trainer']; lb = f['script']
        base = lb.replace('_EventScript_', '_Text_')
        if tr['double']:
            s += '%s::\n\ttrainerbattle_double %s, %sIntro, %sDefeat, %sNotEnough\n\tmsgbox %sPostBattle, MSGBOX_AUTOCLOSE\n\tend\n\n' % (lb, tr['const'], base, base, base, base)
        else:
            s += '%s::\n\ttrainerbattle_single %s, %sIntro, %sDefeat\n\tmsgbox %sPostBattle, MSGBOX_AUTOCLOSE\n\tend\n\n' % (lb, tr['const'], base, base, base)
        for key, part in (('seen', 'Intro'), ('beaten', 'Defeat'), ('after', 'PostBattle')):
            texts += '%s%s::\n' % (base, part) + ''.join('\t.string "%s"\n' % l for l in f[key]) + '\n'
        if tr['double']:
            texts += '%sNotEnough::\n\t.string "We battle two on two! Come\\n"\n\t.string "back with two POKéMON!$"\n\n' % base
    wr(p, t.rstrip('\n') + '\n' + s + texts)
print('johto route trainers ok: %d trainers' % len(trainers))
